  local slash=require('scripts/actions/mobskills/giga_slash');local move,process=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage;local params,damage=nil,nil;local animation=0;local mob={getAnimationSub=function()return animation end,getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};assert(slash.onMobSkillCheck(target,mob,{})==0);animation=1;assert(slash.onMobSkillCheck(target,mob,{})==1);animation=0;xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.SLASHING}end;xi.mobskills.processDamage=function()return false end;assert(slash.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==2.7 and params.fTP[2]==2.7 and params.fTP[3]==2.7 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.SLASHING and params.shadowBehavior==xi.mobskills.shadowBehavior.NUMSHADOWS_1 and params.canCrit and params.criticalChance[1]==.10 and params.criticalChance[2]==.20 and params.criticalChance[3]==.25 and damage==nil);xi.mobskills.processDamage=function()return true end;slash.onMobWeaponSkill(mob,target,{},{})
